    zh:{label:'分类',results:'条结果',order:'商品顺序',sourceOrder:'默认顺序',switch:'选择分类',all:'全部商品',reset:'重置',loading:'正在读取商品',intro:'浏览这一分类的商品。打开商品可查看图片和已核验的购买链接。'},
