  function catalogIntro(t,cat){
    if(state.route==='category'||state.route==='products'){
      const words=categoryWords();
      const inCategory=state.route==='category';
      const name=inCategory?categoryName(cat)||`${words.label} ${state.category}`:t.browse;
      const heading=inCategory?(baseLang()==='en'?`Hipobuy ${name} Spreadsheet`:`Hipobuy ${name}`):t.browse;
      const crumb=inCategory?`<a href="/products">${esc(t.nav[1])}</a><span>/</span><a href="/categories">${esc(t.categories)}</a><span>/</span><span>${esc(name)}</span>`:`<a href="/">${esc(t.nav[0])}</a><span>/</span><span>${esc(name)}</span>`;
      return `<section class="catalog-hero"><div class="shell"><nav class="catalog-crumb" aria-label="Breadcrumb">${crumb}</nav><div class="catalog-hero-row"><div class="catalog-copy"><p class="eyebrow">HIPOBUY / ${esc(inCategory?words.label:t.nav[1])}</p><h1>${esc(heading)}</h1><p>${esc(inCategory?words.intro:t.intro)}</p></div><form class="search" action="/products" method="get" role="search"><label class="sr-only" for="catalog-search">${esc(t.search)}</label><input id="catalog-search" type="search" name="q" value="${esc(state.query)}" placeholder="${esc(t.search)}"><button type="submit">${esc(t.searchButton)} ↗</button></form></div></div></section>`;
    }
    return `<section class="catalog-intro shell"><a href="/" class="text-link">← ${esc(t.nav[0])}</a><p class="eyebrow">HIPOBUY SPREADSHEET</p><h1>${esc(state.route==='categories'?t.categories:t.browse)}</h1>${state.route!=='categories'?`<form class="search" action="/products" method="get" role="search"><label class="sr-only" for="catalog-search">${esc(t.search)}</label><input id="catalog-search" type="search" name="q" value="${esc(state.query)}" placeholder="${esc(t.search)}"><button type="submit">${esc(t.searchButton)} ↗</button></form>`:''}</section>`;
  }
  function categoryToolbar(t,cat){
    const words=categoryWords();
    const [sortLabel,categoryLabel,viewAll,sortLabels]=filterWords();
    const sortValues=['','newest','price_asc','price_desc','views'];
    const currentSort=sortValues.indexOf(state.sort);
    const count=state.loading?words.loading:state.error?state.error:`${state.totalItems.toLocaleString()} ${words.results}`;
    return `<div class="category-results"><a href="${esc(sourceListing())}" target="_blank" rel="noopener noreferrer">${esc(t.original)} ↗</a><span>${esc(count)}</span></div><div class="category-controls"><div class="filter-field"><span>${esc(sortLabel)}</span><details class="filter-picker"><summary aria-label="${esc(sortLabel)}">${esc(sortLabels[currentSort])}<span aria-hidden="true">⌄</span></summary><nav class="filter-options" aria-label="${esc(sortLabel)}">${sortValues.map((value,i)=>`<a href="${esc(sortUrl(value))}" ${state.sort===value?'aria-current="page"':''}>${esc(sortLabels[i])}</a>`).join('')}</nav></details></div><div class="filter-field"><span>${esc(categoryLabel)}</span><details class="filter-picker category-picker"><summary aria-label="${esc(categoryLabel)}">${esc(categoryName(cat)||viewAll)}<span aria-hidden="true">⌄</span></summary><nav class="filter-options category-options" aria-label="${esc(categoryLabel)}"><a href="${esc(categoryUrl(0))}" ${!state.category?'aria-current="page"':''}>${esc(viewAll)}</a>${DATA.categories.map(x=>`<a href="${esc(categoryUrl(x.id))}" ${state.category===x.id?'aria-current="page"':''}>${esc(categoryName(x))}</a>`).join('')}</nav></details></div><a class="category-reset" href="${state.route==='category'?`/category/${state.category}`:'/products'}">${esc(words.reset)}</a></div>${state.error?`<div class="category-error"><button class="outline-button" type="button" data-action="retry">${esc(ui().retry)}</button></div>`:''}`;
  }
